profiles.multi-node:
operatorConfig:
  resources:
    # More Services and Ingresses to reconcile.
    requests: {cpu: 50m, memory: 128Mi}
    limits: {memory: 512Mi}

profiles.single-node:
operatorConfig:
  resources:
    # Chart sets none; one controller and one tailnet node.
    requests: {cpu: 20m, memory: 64Mi}
    limits: {memory: 256Mi}
